import sys

def fwht(a):
    n = len(a)
    step = 1
    while step < n:
        jump = step << 1
        for i in range(0, n, jump):
            for j in range(i, i + step):
                x = a[j]
                y = a[j + step]
                a[j] = x + y
                a[j + step] = x - y
        step = jump

def main():
    input = sys.stdin.buffer.readline
    H, W = map(int, input().split())
    n = 1 << W

    freq = [0] * n
    for _ in range(H):
        s = input().strip()
        mask = 0
        for ch in s:
            mask = (mask << 1) | (ch - 48)
        freq[mask] += 1

    cost = [0] * n
    for mask in range(n):
        ones = mask.bit_count()
        cost[mask] = min(ones, W - ones)

    fwht(freq)
    fwht(cost)

    conv = [freq[i] * cost[i] for i in range(n)]
    fwht(conv)

    ans = min(v // n for v in conv)
    print(ans)

if __name__ == "__main__":
    main()
